//! USB_DPRAM - DPRAM layout for USB device.

#![allow(dead_code)]

pub const BASE: u32 = 0x50100000;

/// SETUP_PACKET_LOW Register
///
/// Bytes 0-3 of the SETUP packet from the host.
///
/// Address offset: 0x0000
/// Reset value: 0x00000000
///
/// ## Fields
///
/// - **WVALUE** [31:16] (RW): 
/// - **BREQUEST** [15:8] (RW): 
/// - **BMREQUESTTYPE** [7:0] (RW): 
#[repr(transparent)]
pub struct SetupPacketLow {
    value: core::cell::UnsafeCell<u32>,
}

unsafe impl Send for SetupPacketLow {}
unsafe impl Sync for SetupPacketLow {}

impl SetupPacketLow {
    // ======== Field Constants ========

    /// Bits [31:16], mask 0xffff0000
    pub const WVALUE_OFFSET: u32 = 16;
    pub const WVALUE_MASK: u32 = 0xffff0000;

    /// Bits [15:8], mask 0x0000ff00
    pub const BREQUEST_OFFSET: u32 = 8;
    pub const BREQUEST_MASK: u32 = 0x0000ff00;

    /// Bits [7:0], mask 0x000000ff
    pub const BMREQUESTTYPE_OFFSET: u32 = 0;
    pub const BMREQUESTTYPE_MASK: u32 = 0x000000ff;

    // ======== Basic Access Methods ========

    /// Read the raw register value as u32
    #[inline(always)]
    pub fn read_bits(&self) -> u32 {
        unsafe { core::ptr::read_volatile(self.value.get()) }
    }

    /// Write a raw u32 value to the register
    #[inline(always)]
    pub fn write_bits(&self, value: u32) {
        unsafe { core::ptr::write_volatile(self.value.get(), value) }
    }

    /// Modify the raw register value
    #[inline(always)]
    pub fn modify_bits<F: FnOnce(u32) -> u32>(&self, f: F) {
        self.write_bits(f(self.read_bits()));
    }

    /// Atomic SET - sets bits that are 1 (hardware alias at +0x2000)
    #[inline(always)]
    pub fn set_bits(&self, bits: u32) {
        unsafe {
            let addr = (self.value.get() as usize + 0x2000) as *mut u32;
            core::ptr::write_volatile(addr, bits);
        }
    }

    /// Atomic CLR - clears bits that are 1 (hardware alias at +0x3000)
    #[inline(always)]
    pub fn clr_bits(&self, bits: u32) {
        unsafe {
            let addr = (self.value.get() as usize + 0x3000) as *mut u32;
            core::ptr::write_volatile(addr, bits);
        }
    }

    /// Atomic XOR - toggles bits that are 1 (hardware alias at +0x1000)
    #[inline(always)]
    pub fn xor_bits(&self, bits: u32) {
        unsafe {
            let addr = (self.value.get() as usize + 0x1000) as *mut u32;
            core::ptr::write_volatile(addr, bits);
        }
    }

    // ======== Field Accessors ========

    /// **WVALUE** [31:16]
    #[inline(always)]
    pub fn wvalue(&self) -> u32 {
        (self.read_bits() & Self::WVALUE_MASK) >> Self::WVALUE_OFFSET
    }

    /// Write WVALUE field
    #[inline(always)]
    pub fn write_wvalue(&self, value: u32) {
        self.modify_bits(|r| (r & !Self::WVALUE_MASK) | ((value << Self::WVALUE_OFFSET) & Self::WVALUE_MASK));
    }

    /// **BREQUEST** [15:8]
    #[inline(always)]
    pub fn brequest(&self) -> u32 {
        (self.read_bits() & Self::BREQUEST_MASK) >> Self::BREQUEST_OFFSET
    }

    /// Write BREQUEST field
    #[inline(always)]
    pub fn write_brequest(&self, value: u32) {
        self.modify_bits(|r| (r & !Self::BREQUEST_MASK) | ((value << Self::BREQUEST_OFFSET) & Self::BREQUEST_MASK));
    }

    /// **BMREQUESTTYPE** [7:0]
    #[inline(always)]
    pub fn bmrequesttype(&self) -> u32 {
        (self.read_bits() & Self::BMREQUESTTYPE_MASK) >> Self::BMREQUESTTYPE_OFFSET
    }

    /// Write BMREQUESTTYPE field
    #[inline(always)]
    pub fn write_bmrequesttype(&self, value: u32) {
        self.modify_bits(|r| (r & !Self::BMREQUESTTYPE_MASK) | ((value << Self::BMREQUESTTYPE_OFFSET) & Self::BMREQUESTTYPE_MASK));
    }

}

